1	package oci
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"strconv"
12		"strings"
13	)
14	
15	// maxCatalogPage bounds one _catalog page: 1000 names of at most 255 bytes fit
16	// well under it.
17	const maxCatalogPage = 1 << 20
18	
19	// ListCatalogContext walks the registry's /v2/_catalog from apiURL, asking
20	// pageSize names per page and following Link rel="next" for at most maxPages
21	// pages. truncated is true when the walk stopped with names left: page cap
22	// reached with a next link, more than maxPages*pageSize names, or a next link
23	// to another origin (never followed: the Basic credentials and the token are
24	// not sent to it). HTTP 3xx redirects follow registryHTTPClient, which refuses
25	// off-origin ones (RefuseOffOriginRedirect, DEVDESK-410).
26	// Authentication is the tag flow's (Basic, then Bearer on a challenge, token
27	// kept across pages); a non-200 answer is a *StatusError.
28	func ListCatalogContext(ctx context.Context, apiURL, username, password string, maxPages, pageSize int) (names []string, truncated bool, err error) {
29		if maxPages <= 0 || pageSize <= 0 {
30			return nil, false, fmt.Errorf("catalog walk needs positive limits, got %d pages of %d", maxPages, pageSize)
31		}
32		next := strings.TrimSuffix(apiURL, "/") + "/v2/_catalog?n=" + strconv.Itoa(pageSize)
33		token := ""
34		for page := 0; next != ""; page++ {
35			if page == maxPages {
36				return names, true, nil
37			}
38			body, link, usedToken, err := registryGETBoundedContext(ctx, next, username, password, token, maxCatalogPage)
39			if err != nil {
40				return nil, false, err
41			}
42			token = usedToken
43			var result struct {
44				Repositories []string `json:"repositories"`
45			}
46			if err := json.Unmarshal(body, &result); err != nil {
47				return nil, false, fmt.Errorf("decode catalog response: %w", err)
48			}
49			names = append(names, result.Repositories...)
50			if len(names) > maxPages*pageSize {
51				return names[:maxPages*pageSize], true, nil
52			}
53			current := next
54			if next = resolveNext(current, link); next != "" && !sameOrigin(current, next) {
55				return names, true, nil
56			}
57		}
58		return names, false, nil
59	}
60	
61	// registryGETBoundedContext is registryGETContext with an explicit body cap:
62	// a body over limit is an error, not a silent cut.
63	func registryGETBoundedContext(ctx context.Context, rawURL, username, password, token string, limit int64) (body []byte, link, usedToken string, err error) {
64		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
65		if err != nil {
66			return nil, "", token, err
67		}
68		defer func() { _ = resp.Body.Close() }()
69		if resp.StatusCode != http.StatusOK {
70			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
71		}
72		body, err = io.ReadAll(io.LimitReader(resp.Body, limit+1))
73		if err == nil && int64(len(body)) > limit {
74			err = errors.New("catalog page over " + strconv.FormatInt(limit, 10) + " bytes")
75		}
76		if err != nil {
77			return nil, "", token, err
78		}
79		return body, resp.Header.Get("Link"), token, nil
80	}
81	
82	// sameOrigin reports whether two absolute URLs share scheme, host and port.
83	func sameOrigin(a, b string) bool {
84		ua, errA := url.Parse(a)
85		ub, errB := url.Parse(b)
86		return errA == nil && errB == nil && ua.Scheme == ub.Scheme && ua.Host == ub.Host
87	}
