1	package oci
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"net/http"
9		"net/http/httptest"
10		"strings"
11		"sync/atomic"
12		"testing"
13		"time"
14	)
15	
16	// These tests pin ListCatalogContext (DEVDESK-306 step 3): a bounded walk of
17	// /v2/_catalog that follows Link rel="next", never leaves the origin, and
18	// reuses the tag flow's authentication.
19	
20	func catalogBody(names ...string) string {
21		b, _ := json.Marshal(map[string][]string{"repositories": names})
22		return string(b)
23	}
24	
25	func numbered(prefix string, from, count int) []string {
26		out := make([]string, count)
27		for i := range out {
28			out[i] = fmt.Sprintf("%s%05d", prefix, from+i)
29		}
30		return out
31	}
32	
33	func TestListCatalogContextPagination(t *testing.T) {
34		var requests atomic.Int32
35		var firstQuery atomic.Value
36		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
37			n := requests.Add(1)
38			if n == 1 {
39				firstQuery.Store(r.URL.Query().Get("n"))
40			}
41			switch r.URL.Query().Get("last") {
42			case "":
43				w.Header().Set("Link", `</v2/_catalog?n=1000&last=a2>; rel="next"`)
44				_, _ = fmt.Fprint(w, catalogBody("a1", "a2"))
45			case "a2":
46				w.Header().Set("Link", `</v2/_catalog?n=1000&last=b2>; rel="next"`)
47				_, _ = fmt.Fprint(w, catalogBody("b1", "b2"))
48			default:
49				_, _ = fmt.Fprint(w, catalogBody("c1"))
50			}
51		}))
52		defer srv.Close()
53	
54		names, truncated, err := ListCatalogContext(context.Background(), srv.URL, "", "", 10, 1000)
55		if err != nil {
56			t.Fatal(err)
57		}
58		if got, want := strings.Join(names, ","), "a1,a2,b1,b2,c1"; got != want {
59			t.Errorf("names = %s, want %s", got, want)
60		}
61		if truncated {
62			t.Error("truncated = true, want false")
63		}
64		if requests.Load() != 3 {
65			t.Errorf("requests = %d, want 3", requests.Load())
66		}
67		if q, _ := firstQuery.Load().(string); q != "1000" {
68			t.Errorf("first request n = %q, want 1000", q)
69		}
70	}
