72	func TestListCatalogContextTrailingSlashBase(t *testing.T) {
73		var path atomic.Value
74		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
75			path.Store(r.URL.Path)
76			_, _ = fmt.Fprint(w, catalogBody("a"))
77		}))
78		defer srv.Close()
79		if _, _, err := ListCatalogContext(context.Background(), srv.URL+"/", "", "", 1, 10); err != nil {
80			t.Fatal(err)
81		}
82		if p, _ := path.Load().(string); p != "/v2/_catalog" {
83			t.Errorf("path = %q, want /v2/_catalog", p)
84		}
85	}
