87	func TestListCatalogContextBounds(t *testing.T) {
88		t.Run("endless next stops at maxPages", func(t *testing.T) {
89			var requests atomic.Int32
90			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
91				n := int(requests.Add(1))
92				w.Header().Set("Link", fmt.Sprintf(`</v2/_catalog?n=1000&last=p%d>; rel="next"`, n))
93				_, _ = fmt.Fprint(w, catalogBody(numbered("r", n*1000, 1000)...))
94			}))
95			defer srv.Close()
96	
97			names, truncated, err := ListCatalogContext(context.Background(), srv.URL, "", "", 10, 1000)
98			if err != nil {
99				t.Fatal(err)
100			}
101			if requests.Load() != 10 {
102				t.Errorf("requests = %d, want 10", requests.Load())
103			}
104			if !truncated {
105				t.Error("truncated = false, want true")
106			}
107			if len(names) != 10000 {
108				t.Errorf("len(names) = %d, want 10000", len(names))
109			}
110		})
111	
112		t.Run("page larger than pageSize is cut", func(t *testing.T) {
113			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
114				_, _ = fmt.Fprint(w, catalogBody(numbered("r", 0, 1500)...))
115			}))
116			defer srv.Close()
117	
118			names, truncated, err := ListCatalogContext(context.Background(), srv.URL, "", "", 1, 1000)
119			if err != nil {
120				t.Fatal(err)
121			}
122			if len(names) != 1000 {
123				t.Errorf("len(names) = %d, want 1000", len(names))
124			}
125			if !truncated {
126				t.Error("truncated = false, want true")
127			}
128		})
129	
130		for _, tt := range []struct {
131			name             string
132			maxPages, pgSize int
133		}{
134			{"zero maxPages", 0, 1000},
135			{"negative maxPages", -1, 1000},
136			{"zero pageSize", 10, 0},
137			{"negative pageSize", 10, -5},
138		} {
139			t.Run(tt.name, func(t *testing.T) {
140				var requests atomic.Int32
141				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
142					requests.Add(1)
143				}))
144				defer srv.Close()
145				_, _, err := ListCatalogContext(context.Background(), srv.URL, "", "", tt.maxPages, tt.pgSize)
146				if err == nil {
147					t.Fatal("err = nil, want an error")
148				}
149				if requests.Load() != 0 {
150					t.Errorf("requests = %d, want 0", requests.Load())
151				}
152			})
153		}
154	}
155	
156	func TestListCatalogContextNextOrigin(t *testing.T) {
157		var otherHits atomic.Int32
158		var otherAuth atomic.Value
159		other := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
160			otherHits.Add(1)
161			otherAuth.Store(r.Header.Get("Authorization"))
162			_, _ = fmt.Fprint(w, catalogBody("evil"))
163		}))
164		defer other.Close()
165	
166		t.Run("other origin is not followed", func(t *testing.T) {
167			srvOther := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
168				w.Header().Set("Link", `<`+other.URL+`/v2/_catalog?last=x>; rel="next"`)
169				_, _ = fmt.Fprint(w, catalogBody("first"))
170			}))
171			defer srvOther.Close()
172	
173			names, truncated, err := ListCatalogContext(context.Background(), srvOther.URL, "user", "pass", 10, 1000)
174			if err != nil {
175				t.Fatalf("err = %v, want a partial walk without error", err)
176			}
177			if got := strings.Join(names, ","); got != "first" {
178				t.Errorf("names = %s, want first", got)
179			}
180			if !truncated {
181				t.Error("truncated = false, want true")
182			}
183			if otherHits.Load() != 0 {
184				t.Errorf("other origin hit %d times, want 0", otherHits.Load())
185			}
186			if a, _ := otherAuth.Load().(string); a != "" {
187				t.Errorf("credentials reached the other origin: %q", a)
188			}
189		})
190	
191		for _, tt := range []struct {
192			name string
193			link func(self string) string
194		}{
195			{"relative next is followed", func(string) string { return "/v2/_catalog?last=x" }},
196			{"same-origin absolute next is followed", func(self string) string { return self + "/v2/_catalog?last=x" }},
197		} {
198			t.Run(tt.name, func(t *testing.T) {
199				var s *httptest.Server
200				s = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
201					if r.URL.Query().Get("last") == "" {
202						w.Header().Set("Link", `<`+tt.link(s.URL)+`>; rel="next"`)
203						_, _ = fmt.Fprint(w, catalogBody("first"))
204						return
205					}
206					_, _ = fmt.Fprint(w, catalogBody("second"))
207				}))
208				defer s.Close()
209	
210				names, truncated, err := ListCatalogContext(context.Background(), s.URL, "", "", 10, 1000)
211				if err != nil {
212					t.Fatal(err)
213				}
214				if got := strings.Join(names, ","); got != "first,second" {
215					t.Errorf("names = %s, want first,second", got)
216				}
217				if truncated {
218					t.Error("truncated = true, want false")
219				}
220			})
221		}
222	}
223	
224	func TestSameOrigin(t *testing.T) {
225		tests := []struct {
226			a, b string
227			want bool
228		}{
229			{"https://r.io/v2/_catalog", "https://r.io/v2/_catalog?last=x", true},
230			{"https://r.io/a", "http://r.io/a", false},
231			{"https://r.io/a", "https://other.io/a", false},
232			{"https://r.io/a", "https://r.io:8443/a", false},
233			{"http://127.0.0.1:5000/a", "http://127.0.0.1:5000/b", true},
234			{"http://127.0.0.1:5000/a", "http://127.0.0.1:5001/b", false},
235		}
